body:
{options && // display each option in select
  Object.entries(options).map(([key, optionLabel]) => (
    <MenuItem key={key} value={key}>
      {optionLabel}
    </MenuItem>
  ))}

{label}
{(!isModifiable ||
  fieldStatus === IntakeFormFieldStatus.Hidden) && (
  <SvgIcon
    component={getLabelIcon()}
    sx={{
      position: "absolute",
      right: 0,
      color: theme.palette.grey[500],
      fontSize: "1.25rem",
    }}
  />
)}

{activeInsuranceCases?.map((c) => (
  <MenuItem
    key={c.patientCaseId}
    value={c.patientCaseId}
    data-testid={`insurance-case-option-${c.patientCaseId}`}
  >
    {c.name}
  </MenuItem>
))}
{/* hide selected inactive case from the options list */}
{selectedCaseIsInactive && (
  <MenuItem
    key={selectedPatientCase.patientCaseId}
    value={selectedPatientCase.patientCaseId}
    sx={{ display: "none" }}
  >
    {selectedPatientCase.name}
  </MenuItem>
)}

{serviceLocations.map((location: ServiceLocationObj) => (
  <MenuItem
    key={location.serviceLocationGuid}
    value={location.serviceLocationGuid}
  >
    <Box
      display="flex"
      alignItems="center"
      justifyContent="space-between"
      gap={1}
      overflow="hidden"
      width="100%"
    >
      <Box>{location.name}</Box>
      {patients?.length > 0 &&
        patientDefaultServiceLocationGuid ===
          location.serviceLocationGuid && (
          <Box>(Patient-Preferred)</Box>
        )}
    </Box>
  </MenuItem>
))}

{Array.from({ length: 24 }, (_, i) => (
  <MenuItem
    key={i}
    value={i}
    disabled={i > watch("customEndHour") - 1}
  >
    {formatHour(i)}
  </MenuItem>
))}

{Array.from({ length: 24 }, (_, i) => (
  <MenuItem
    key={i}
    value={i}
    disabled={i < watch("customStartHour") + 1}
  >
    {formatHour(i)}
  </MenuItem>
))}

Encounter forms by last name
{printingTemplate === "encounterFormsByLastName" && isPrinting && (
  <ListItemIcon>
    <CircularProgress color="primary" size="1rem" />
  </ListItemIcon>
)}

Encounter forms by time
{printingTemplate === "encounterFormsByTime" && isPrinting && (
  <ListItemIcon>
    <CircularProgress color="primary" size="1rem" />
  </ListItemIcon>
)}

            {rangeValues.map(({ value, name }, index) => {
              let disabled;
              if (getDisabledStatus) {
                disabled = getDisabledStatus(value);
              } else {
                disabled = isStartOfRange
                  ? value > otherRangeValue
                  : value < otherRangeValue;
              }

              return (
                <MenuItem key={index} value={value} disabled={disabled}>
                  {name}
                </MenuItem>
              );
            })}

{filterOptions.map((option) => (
  <MenuItem key={option.id} value={option.name}>
    <Checkbox
      checked={selected.indexOf(option) > -1}
      onChange={(_, checked) => {
        if (!checked) {
          const newSelectedOptions = selected.filter(
            (selectedOption) => selectedOption.id !== option.id,
          );
          setSelected(newSelectedOptions);
        }
      }}
    />
    <ListItemText primary={option.name} />
  </MenuItem>
))}

{StatusOptions.filter(
  (item: (typeof StatusOptions)[number]) =>
    // Only show statuses other than current status in dropdown
    item.value !== status
).map((item: (typeof StatusOptions)[number]) => (
  <MenuItem
    key={item.value}
    value={item.value}
    onClick={() => handleClickMenuItem(item)}
  >
    {item.label}
  </MenuItem>
))}

{errors && (
  <FormHelperText>Please confirm acknowledgement</FormHelperText>
)}
<FormControlLabel
  control={
    <Checkbox
      required
      checked={formData.confirmed}
      onChange={handleChange}
    />
  }
  label="I acknowledge the information I have entered is correct"
/>

{Object.entries(documentStatusLabels)
  .filter(([, { isSelectable }]) => isSelectable)
  .map(([status, { label }]) => (
    <MenuItem
      key={status}
      value={status}
      data-testid={`status-option-${status}`}
    >
      {label}
    </MenuItem>
  ))}

{CaseStatusOptions.filter(
  (item: (typeof CaseStatusOptions)[number]) =>
    // only show statuses other than current status in dropdown
    item.value !== status
).map((item: (typeof CaseStatusOptions)[number]) => (
  <MenuItem
    key={item.value}
    value={item.value}
    onClick={() => handleClickMenuItem(item)}
  >
    {item.label}
  </MenuItem>
))}

{items.map((item) => (
  <MenuItem
    key={item.id}
    selected={item.id === activeItemId}
    onClick={() => handleSelect(item.id)}
  >
    <ListItemIcon>{getNavIcon(item.iconName)}</ListItemIcon>
    <ListItemText>{item.label}</ListItemText>
    <InboxNavCount count={item.unreadCount} />
  </MenuItem>
))}

{Object.entries(UnreadState).map(([key, value]) => (
  <MenuItem key={key} value={value}>
    {UnreadStateLabel[key as keyof typeof UnreadStateLabel]}
  </MenuItem>
))}

{AI_TAGS_LIST.map((tag) => {
  const isChecked = tagsFilter.includes(tag);
  return (
    <MenuItem key={tag} value={tag}>
      <ListItemIcon>
        <Checkbox checked={isChecked} size="small" />
      </ListItemIcon>
      <ListItemText primary={tag} />
    </MenuItem>
  );
})}

{AI_TAGS_LIST.map((tagName) => {
  const isChecked = isTagSelected(tagName);
  return (
    <MenuItem
      key={tagName}
      onClick={() => onAddOrDeleteTag(tagName, isChecked)}
      disabled={isTagDisabled(tagName)}
    >
      <ListItemIcon>
        <Checkbox
          checked={isChecked}
          size="small"
          disabled={isTagDisabled(tagName)}
        />
      </ListItemIcon>
      <ListItemText primary={tagName} />
    </MenuItem>
  );
})}

{appointmentList.map((appt: Appointment) => {
  return (
    <MenuItem
      data-occurrence-id={appt.occurrenceId}
      key={`${appt.appointmentGuid}-${appt.occurrenceId}`}
      value={appt.appointmentGuid}
    >
      <Typography variant="body1" color="grey.900">
        {formatDate(appt.startTime)}
      </Typography>
    </MenuItem>
  );
})}
<Box>
  <LocalizationProvider dateAdapter={AdapterLuxon}>
    <ButtonDateTimePicker
      handleDatePickerClose={handleDatePickerClose}
      handleAccept={handleSetDate}
      onChange={(newValue) => handleTimeChange(newValue)}
      onClose={handleDatePickerClose}
      selectRef={selectRef}
      value={dateTime}
    />
  </LocalizationProvider>
</Box>

{overrideReasonsFilterOptions.map(
  (option: string) =>
    option && (
      <MenuItem key={option} value={option}>
        <Typography
          color={
            option === mustProvideReasons
              ? "error.main"
              : "text.primary"
          }
          noWrap
        >
          {option}
        </Typography>
      </MenuItem>
    ),
)}

{Object.values(SortBy).map((option) => {
  return (
    <MenuItem key={option} value={option}>
      <Box display="flex" justifyContent="space-between" width="100%">
        <Typography>{option}</Typography>
      </Box>
    </MenuItem>
  );
})}

{providers.map((provider) => {
  return (
    <MenuItem
      key={provider.providerGuid}
      value={`provider ${provider.providerGuid}`}
    >
      <Box
        display="flex"
        justifyContent="space-between"
        width="100%"
        alignItems="center"
      >
        <Typography>{provider.name}</Typography>
      </Box>
    </MenuItem>
  );
})}
{serviceLocations.map((serviceLocation) => {
  return (
    <MenuItem
      key={serviceLocation.guid}
      value={`location ${serviceLocation.guid}`}
    >
      <Box
        display="flex"
        justifyContent="space-between"
        width="100%"
        alignItems="center"
      >
        <Typography>{serviceLocation.name}</Typography>
      </Box>
    </MenuItem>
  );
})}

{Object.values(SortBy).map((option) => {
  return (
    <MenuItem key={option} value={option}>
      <Box display="flex" justifyContent="space-between" width="100%">
        <Typography
          data-testid={`sort-by-option-${option
            .toLowerCase()
            .replace(/\s/g, "-")}`}
        >
          {option}
        </Typography>
      </Box>
    </MenuItem>
  );
})}

{FilterBy.map((option, i) => {
  return (
    <MenuItem key={option} value={option}>
      <Box
        display="flex"
        justifyContent="space-between"
        width="100%"
        data-testid={`filter-by-option-${option
          .toLowerCase()
          .replace(/\s/g, "-")}`}
      >
        {i === 0 ? (
          <>{option}</>
        ) : (
          <Rating
            size="small"
            name="read-only"
            value={parseInt(option)}
            readOnly
          />
        )}
      </Box>
    </MenuItem>
  );
})}

{selectionOptions?.map((option: string) => (
  <StyledFormControlLabel
    key={option}
    value={option}
    pdfPrintMode={pdfPrintMode}
    control={
      <StyledCheckbox
        size="small"
        onChange={handleChange}
        checked={value?.includes(option)}
      />
    }
    label={option}
  />
))}

{pharmacies.length > 0 ? (
  <PharmacyList
    pharmacies={pharmacies}
    renderActionCell={(pharmacy) => (
      <IconButton
        size="small"
        onClick={() => handlePharmacyRemove(pharmacy.pharmacyId)}
        sx={{ p: 0 }}
      >
        <TrashOutlinedIcon fontSize="small" />
      </IconButton>
    )}
  />
) : (
  <StyledBox>
    <Typography align="center">
      Add your first pharmacy by clicking the “Add Pharmacies” button
    </Typography>
  </StyledBox>
)}
<FormHelperText sx={{ color: "error.main" }}>
  {error?.message}
</FormHelperText>

{menuSubscriber ? (
  <SubscriberActionMenuItems
    showPaymentRecoveryActions={showPaymentRecoveryActions}
    subscriber={menuSubscriber}
    onAction={openAction}
    onRetryPayment={
      showPaymentRecoveryActions ? openRetryPaymentDialog : undefined
    }
  />
) : null}
